  while(bits.length%8)bits.push(0);
  for(var pad=0xEC;bits.length<cap;pad^=0xEC^0x11)put(pad,8);
  var data=[];for(i=0;i<bits.length;i+=8){var bv=0;for(j=0;j<8;j++)bv=bv<<1|bits[i+j];data.push(bv)}
